draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 10*Math.sin(t), H/2 + 50 + 10*Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 10*Math.sin(t), H/2 + 50 + 10*Math.sin(t));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 - 20 + 10*Math.cos(t), H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 + 20 + 10*Math.cos(t), H/2 + 70);
  ctx.stroke();

  // guilt weight
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  ctx.restore();
}
